toolUseResult.newString:
if n <= _TINY_MAXN:
    # n=32 (B=20): the single-launch batch-major panel (BLK=n, one
    # _panel_factor_kernel, no trailing) beats the spill-bound warp-per-matrix
    # qr_tiny -- more parallelism (128 threads/matrix vs 1 warp), no 88-reg
    # spill, ~22us GPU vs 46.9us, and still ONE launch so host cost stays low.
    if _N32_ROUTE == 1:
        return _w2_qr(data, blk_override=n)
    return _tiny_qr(data)
if n in _SMALL_N:
    return _small_qr(data)
